def is_match(s: str, p: str) -> bool:
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[-1][-1] = True
    for i in range(len(s), -1, -1):
        for j in range(len(p) - 1, -1, -1):
            if p[j] in {s[i], '.'}:
                dp[i][j] = dp[i + 1][j + 1]
            elif p[j] == '*':
                dp[i][j] = dp[i + 1][j + 1] or (i < len(s) and dp[i + 1][j] and (p[j - 1] in {s[i], '.'}))
    return dp[0][0]

